def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_count += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.35)

    scarcity = WATER_REQ / max(1.0, supply)
    severe_need = hp <= 3 or no_water_days >= 1
    moderate_need = hp <= 5

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0
        avg_prev = 0

    if severe_need:
        bid = max(DAILY_SALARY * 0.9, highest_prev + 2)
    elif scarcity > 0.75:
        if highest_prev >= DAILY_SALARY * 0.85:
            bid = DAILY_SALARY * (0.42 if hp > 6 else 0.88)
        else:
            bid = max(DAILY_SALARY * 0.62, avg_prev + 2)
    elif scarcity > 0.6:
        if desperate_count >= 1:
            bid = max(DAILY_SALARY * 0.58, highest_prev + 1)
        else:
            bid = max(DAILY_SALARY * 0.48, avg_prev)
    else:
        bid = DAILY_SALARY * 0.34
        if moderate_need:
            bid = DAILY_SALARY * 0.5

    if rich_count >= 2 and not severe_need:
        bid *= 0.92

    if hp >= 8 and no_water_days == 0 and highest_prev >= DAILY_SALARY * 0.9:
        bid = min(bid, DAILY_SALARY * 0.38)

    reserve = 0
    if hp <= 4:
        reserve = DAILY_SALARY * 0.15
    elif hp <= 6:
        reserve = DAILY_SALARY * 0.08

    final_bid = min(budget - reserve, bid)
    if severe_need:
        final_bid = min(budget, max(final_bid, DAILY_SALARY * 0.88))

    if final_bid < 0:
        final_bid = 0
    if final_bid > budget:
        final_bid = budget
    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Identify alive opponents
    alive_opponents = []
    for k, o in opponents_status.items():
        if o is not None and o.get('alive', False):
            alive_opponents.append(o)

    # Baseline bid logic: aim to be competitive but not reckless
    # Target share: if supply is low, bid higher; if high, bid moderate.
    # supply in [15,25] => need 1 unit of requirement is 9; typically 2 players may compete.
    if supply <= float(WATER_REQ + 6):
        base = DAILY_SALARY * 0.65
    elif supply <= float(WATER_REQ + 10):
        base = DAILY_SALARY * 0.58
    else:
        base = DAILY_SALARY * 0.50

    # React to yesterday's aggressive bids (immediate reaction only)
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) if isinstance(o.get('previous_trace', {}), dict) else {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If they were bidding near-salary, assume high urgency; slightly outbid if we can.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status.get('hp', 0) > 3:
                base = max(base, highest_prev_bid * 1.02)
            else:
                base = max(base, highest_prev_bid * 1.05)
        # If they were bidding low, we can take initiative moderately.
        elif highest_prev_bid <= DAILY_SALARY * 0.45:
            base = max(base, DAILY_SALARY * 0.56)
        else:
            # Keep close to their level to avoid underbidding.
            base = max(base, highest_prev_bid * 1.01)

    # HP/budget risk management
    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # If we are close to starvation or low HP, bid harder.
    if hp <= 2.0 or no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.75)
    elif hp <= 3.0:
        base = max(base, DAILY_SALARY * 0.62)

    # Budget cap: never exceed budget.
    bid = min(budget, base)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    # Return as float (game typically accepts numeric)
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # Base bid values relative to daily salary
    bid_low = DAILY_SALARY * 0.3
    bid_medium = DAILY_SALARY * 0.5
    bid_high = DAILY_SALARY * 0.7
    bid_critical = DAILY_SALARY * 0.9
    bid_desperate = DAILY_SALARY * 0.95 # Even higher for extreme cases

    # 1. No opponents: Bid minimally to save budget, guaranteed water.
    if num_alive_opponents == 0:
        return min(my_budget, max(1, WATER_REQ * 0.1))

    # 2. Survival mode: Prioritize getting water if HP is low or missed water yesterday.
    if my_no_water_days >= 1 or my_hp <= 2:
        if my_hp <= 1: # Extremely critical, bid very high
            return min(my_budget, bid_desperate)
        return min(my_budget, bid_critical) # Critical, bid high

    # 3. Assess supply vs demand to adjust bid based on competition intensity.
    total_req_by_alive_players = WATER_REQ + sum(o['water_requirement'] for o in alive_opponents)

    # If supply is abundant for everyone, bid lower to save budget.
    if current_supply >= total_req_by_alive_players:
        # If my HP is not perfect, still bid reasonably to secure water just in case.
        if my_hp <= 3:
            return min(my_budget, bid_medium)
        return min(my_budget, bid_low)

    # If supply is scarce (not enough for everyone's full requirement), competition will be higher.
    if num_alive_opponents == 1:
        # Direct competition. If supply is very tight for two players, bid higher.
        if current_supply < WATER_REQ * 1.5: 
            return min(my_budget, bid_high)
        return min(my_budget, bid_medium) # Standard competition bid

    if num_alive_opponents >= 2:
        # Multiple opponents and scarce supply, bid high due to intense competition.
        return min(my_budget, bid_high)

    # Default fallback bid if no specific condition is met (should ideally not be reached).
    return min(my_budget, bid_medium)

